package ro.leo.visual;
import android.content.*;import java.io.*;import java.util.*;import java.util.zip.*;import org.json.*;
/** Offline HTML packages, with bounded extraction and a separate origin per app. */
final class WebAppPackages {
 static File base(Context c){File f=new File(c.getFilesDir(),"web-apps");f.mkdirs();return f;}
 static boolean validId(String id){return id!=null&&!id.startsWith("stage-")&&id.matches("[a-z][a-z0-9-]{0,39}");}
 static boolean safePath(String path){if(path==null||path.length()>=160||path.startsWith("/")||path.contains("\\")||path.contains(":"))return false;for(String part:path.split("/",-1))if(part.equals("..")||part.equals(".")||part.isEmpty())return false;return true;}
 static JSONObject manifest(File dir)throws Exception{JSONObject m=new JSONObject(new String(BackupEngine.bytes(new File(dir,"manifest.json"),8192),"UTF-8"));String id=m.getString("id"),entry=m.getString("entry");if(!validId(id)||!safePath(entry)||m.getString("name").length()>60||m.getString("name").trim().isEmpty()||!new File(dir,entry).isFile()||!entry.endsWith(".html"))throw new IOException("Invalid web manifest");return m;}
 static synchronized String install(Context c,File zip)throws Exception{if(!ReaderActivity.allowed(c,zip)||zip.length()>2097152)throw new IOException("Select a local ZIP below 2 MB");File stage=new File(base(c),"stage-"+UUID.randomUUID());stage.mkdir();try{HashSet<String> names=new HashSet<String>();long total=0;try(ZipInputStream in=new ZipInputStream(new FileInputStream(zip))){ZipEntry entry;while((entry=in.getNextEntry())!=null){String name=entry.getName();if(entry.isDirectory()){if(!safePath(name.replaceFirst("/$","")))throw new IOException("Invalid folder");continue;}if(!safePath(name)||!names.add(name)||names.size()>64)throw new IOException("Invalid or duplicate entry");File target=new File(stage,name);if(!LeoFileProvider.inside(stage,target))throw new IOException();target.getParentFile().mkdirs();try(FileOutputStream out=new FileOutputStream(target)){byte[] bytes=new byte[8192];int n;long count=0;while((n=in.read(bytes))!=-1){count+=n;total+=n;if(count>524288||total>2097152)throw new IOException("Package too large");out.write(bytes,0,n);}out.getFD().sync();}}}JSONObject m=manifest(stage);String id=m.getString("id");File destination=new File(base(c),id);if(destination.exists())throw new IOException("App exists; remove it first");if(!stage.renameTo(destination))throw new IOException("Install failed");return id;}finally{if(stage.exists())UpdateEngine.delete(stage);}}
 static ArrayList<JSONObject> apps(Context c){ArrayList<JSONObject> out=new ArrayList<JSONObject>();File[] dirs=base(c).listFiles();if(dirs!=null)for(File dir:dirs)if(validId(dir.getName())&&!dir.getName().startsWith("stage-"))try{JSONObject m=manifest(dir);if(dir.getName().equals(m.getString("id")))out.add(m);}catch(Exception ignored){}Collections.sort(out,new Comparator<JSONObject>(){public int compare(JSONObject x,JSONObject y){return x.optString("name").compareToIgnoreCase(y.optString("name"));}});return out;}
 static void stock(Context c)throws Exception{File dir=new File(base(c),"pocket-board");if(dir.isDirectory())return;dir.mkdir();try(InputStream in=c.getAssets().open("pocket-board.html");FileOutputStream out=new FileOutputStream(new File(dir,"index.html"))){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);}BackupEngine.write(new File(dir,"manifest.json"),"{\"id\":\"pocket-board\",\"name\":\"Pocket Board\",\"entry\":\"index.html\"}".getBytes("UTF-8"));}
}
